<script setup>
import {Head, Link, useForm, usePage} from '@inertiajs/vue3';
import { Divider } from 'primevue';
import {computed, ref} from "vue";
import { useI18n } from 'vue-i18n';

const { t } = useI18n();
const props = defineProps(['errors']);
const page = usePage();
const recaptchaSiteKey = page.props.recaptcha_site_key;

const userTypes = computed(() => [
    { key: 'individual', value: t('auth.individual') },
    { key: 'legal_entity', value: t('auth.legalEntity') },
]);
const selectedUserType = ref({ key: 'individual', value: t('auth.individual') });

const selectedCountryCode = ref('GE');

const form = useForm({
    user_type: null,
    name: null,
    lastname: null,
    phone_country: selectedCountryCode.value,
    phone: null,
    tax_id: null,
    is_foreign_resident: false,
    email: null,
    password: null,
    password_confirmation: null,
    captcha_token: null,
})

async function register(){
    form.captcha_token = await grecaptcha.enterprise.execute(recaptchaSiteKey, { action: 'signup' });

    if (selectedUserType.value?.key !== 'individual') {
        delete form.lastname
    }

    form.transform((data) => ({
        ...data,
        user_type: selectedUserType.value ? selectedUserType.value?.key : null,
    })).post(route('register'), {
        preserveState: true,
    })
}

</script>

<template>
    <Head>
        <title>{{ $t('auth.registerTitle') }}</title>
    </Head>

    <div class="w-full max-w-md mx-auto my-6">
        <!-- Register Card -->
        <div class="bg-white mx-3 rounded-xl shadow-lg transition-shadow duration-500 ease-in-out border transiton-all border-gray-200 p-8">
            <h1 class="text-2xl font-bold text-gray-800 text-center">{{ $t('auth.registerHeading') }}</h1>

            <div class="flex justify-center my-4">
                <SelectButton v-model="selectedUserType" optionLabel="key" :allow-empty="false" :options="userTypes">
                    <template #option="slotProps">
                        <p>{{ slotProps.option.value }}</p>
                    </template>
                </SelectButton>
            </div>
            <!-- Form Validation Errors -->
            <div v-if="Object.keys(errors).length > 0" class="mb-6 bg-red-50 border border-red-200 rounded-lg p-4 flex">
                <i class="pi pi-exclamation-circle text-red-400 mr-3 mt-0.5"></i>
                <div class="text-red-600 text-sm">
                    <p v-for="(error, key) in errors" :key="key">{{ error }}</p>
                </div>
            </div>

            <!-- Register Form -->
            <form @submit.prevent="register" class="flex flex-col gap-6">
                <!-- Foreign Resident Checkbox -->
                <div class="flex flex-col gap-2">
                    <div class="flex items-center gap-2">
                        <Checkbox v-model="form.is_foreign_resident" size="medium" inputId="is_foreign_resident" binary />
                        <label for="is_foreign_resident" class="text-sm">
                            {{ $t('auth.nonResident') }}
                        </label>
                    </div>
                </div>

                <!-- Name Field -->
                <InputGroup>
                    <InputGroupAddon>
                        <i class="pi pi-user text-gray-400"></i>
                    </InputGroupAddon>
                    <FloatLabel variant="on">
                        <InputText
                            id="name"
                            v-model="form.name"
                            :invalid="!!form.errors.name"
                        />
                        <label for="name">
                            {{ selectedUserType?.key === 'individual' ? $t('auth.firstName') : $t('auth.companyName') }}
                        </label>
                    </FloatLabel>
                </InputGroup>

                <!-- Lastname Field -->
                <InputGroup v-if="selectedUserType?.key === 'individual'">
                    <InputGroupAddon>
                        <i class="pi pi-users text-gray-400"></i>
                    </InputGroupAddon>
                    <FloatLabel variant="on">
                        <InputText
                            id="lastname"
                            v-model="form.lastname"
                            :invalid="!!form.errors.lastname"
                        />
                        <label for="lastname">
                            {{ $t('auth.lastName') }}
                        </label>
                    </FloatLabel>
                </InputGroup>

                <!-- Mobile Field -->
                <InputGroup>
                    <InputGroupAddon>
                        <i class="pi pi-mobile text-gray-400"></i>
                    </InputGroupAddon>
                    <FloatLabel variant="on">
                        <InputText
                            v-keyfilter="{ pattern: /[\d+]+$/, validateOnly: true }"
                            id="phone"
                            v-model="form.phone"
                            :invalid="!!form.errors.phone"
                        />
                        <label for="phone">
                            {{ $t('auth.phone') }}
                        </label>
                    </FloatLabel>
                </InputGroup>

                <!-- ID Number Field -->
                <InputGroup>
                    <InputGroupAddon>
                        <i class="pi pi-id-card text-gray-400"></i>
                    </InputGroupAddon>
                    <FloatLabel variant="on">
                        <InputText
                            v-keyfilter="{ pattern: /[\d+]+$/, validateOnly: true }"
                            id="id-number"
                            v-model="form.tax_id"
                            :maxlength="11"
                            :invalid="!!form.errors.tax_id"
                        />
                        <label for="id-number">{{ selectedUserType?.key === 'individual' ? $t('auth.personalId') : $t('auth.identificationNumber') }}</label>
                    </FloatLabel>
                </InputGroup>

                <!-- Email Field -->
                <InputGroup>
                    <InputGroupAddon>
                        <i class="pi pi-envelope text-gray-400"></i>
                    </InputGroupAddon>
                    <FloatLabel variant="on">
                        <InputText
                            id="email"
                            v-model="form.email"
                            :invalid="!!form.errors.email"
                        />
                        <label for="email">{{ $t('auth.email') }}</label>
                    </FloatLabel>
                </InputGroup>

                <!-- Password Field -->
                <InputGroup>
                    <InputGroupAddon>
                        <i class="pi pi-lock text-gray-400"></i>
                    </InputGroupAddon>
                    <FloatLabel variant="on">
                        <Password
                            v-model="form.password"
                            inputId="password"
                            toggleMask
                            pt:maskIcon:class="z-10"
                            pt:unmaskIcon:class="z-10"
                            :feedback="false"
                            :invalid="!!form.errors.password"
                        />
                        <label for="password">
                            {{ $t('auth.password') }}
                        </label>
                    </FloatLabel>
                </InputGroup>

                <!-- Confirm Password Field -->
                <InputGroup>
                    <InputGroupAddon>
                        <i class="pi pi-lock text-gray-400"></i>
                    </InputGroupAddon>
                    <FloatLabel variant="on">
                        <Password
                            v-model="form.password_confirmation"
                            inputId="password_confirm"
                            toggleMask
                            pt:maskIcon:class="z-10"
                            pt:unmaskIcon:class="z-10"
                            :feedback="false"
                            :invalid="!!form.errors.password_confirmation"
                        />
                        <label for="password_confirm">
                            {{ $t('auth.repeatPassword') }}
                        </label>
                    </FloatLabel>
                </InputGroup>

                <p>{{ $t('auth.entrepreneurNote') }}</p>
                <!-- Submit Button -->
                <div>
                    <Button
                        type="submit"
                        icon="pi pi-user-plus"
                        :label="$t('auth.confirm')"
                        class="w-full bg-blue-500 hover:bg-blue-500/90 border-none text-white rounded-lg py-2.5"
                    />
                </div>

                <Divider pt:root:class="m-0"></Divider>
                <div>
                    <div class="flex justify-center gap-x-2 text-sm">
                        <p class="w-fit">{{ $t('auth.alreadyRegistered') }}</p>
                        <!-- Login Link -->
                        <div class="flex items-center w-fit gap-x-2 text-nowrap">
                            <Link :href="route('login')" class="flex items-center gap-x-1 text-brand-500 text-sm no-underline">
                                <i class="pi pi-user text-brand-500"></i>
                                {{ $t('auth.signIn') }}
                            </Link>
                        </div>
                    </div>
                </div>
            </form>
        </div>
    </div>
</template>

<style scoped>
.p-inputtext:focus {
    box-shadow: none;
}
</style>
